const body = $input.first().json.body ?? $input.first().json;
const token = $input.first().json.headers?.['x-webhook-token']
           ?? $input.first().json.headers?.['X-Webhook-Token']
           ?? '';
const expectedToken = $env.WEBHOOK_TOKEN ?? '';
if (expectedToken && token !== expectedToken) throw new Error('Token inválido');

const event          = body.event ?? 'appointment.created';
const appointmentId  = body.appointment_id;
const clientId       = body.client_id;

if (!appointmentId) throw new Error('appointment_id é obrigatório');
if (!clientId)      throw new Error('client_id é obrigatório');

const validEvents = ['appointment.created','appointment.updated','appointment.cancelled'];
if (!validEvents.includes(event)) throw new Error('Evento inválido: ' + event);

// Normaliza evento para o formato esperado pelo dispatcher
const eventMap = {
  'appointment.created':   'created',
  'appointment.updated':   'confirmed',
  'appointment.cancelled': 'cancelled',
};

console.log(`[agenda-upsert] ${event} | appointment=${appointmentId} | client=${clientId}`);

return [{ json: {
  event,
  event_normalized: eventMap[event] ?? 'created',
  appointment_id: appointmentId,
  client_id:      clientId,
  source:         body.source ?? 'manual',
} }];

const result  = $input.first().json;
const payload = $('Validar e Normalizar').first().json;

const appt = Array.isArray(result) ? result[0] : null;
if (!appt) {
  console.error(`[agenda-upsert] Agendamento ${payload.appointment_id} não encontrado para client=${payload.client_id}.`);
  return [];
}

return [{ json: {
  event:              payload.event,
  event_normalized:   payload.event_normalized,
  source:             payload.source,
  appointment_id:     appt.id,
  client_id:          appt.client_id,
  customer_name:      appt.customer_name,
  customer_phone:     appt.customer_phone,
  customer_email:     appt.customer_email,
  service_name:       appt.service_name,
  start_at:           appt.start_at,
  end_at:             appt.end_at,
  status:             appt.status,
  google_event_id:    appt.google_event_id    ?? null,
  google_calendar_id: appt.google_calendar_id ?? null,
  notes:              appt.notes,
  whatsapp_notify_phone: appt.whatsapp_notify_phone ?? appt.customer_phone,
} }];

const tokens = $input.first().json;
const appt   = $('Enriquecer com Dados do Banco').first().json;

if (!tokens?.found) {
  console.log(`[agenda-upsert] Cliente ${appt.client_id} sem Google Calendar conectado. Agendamento salvo apenas no Banco A.`);
  // Mesmo sem GCal, dispara notificações
  return [{ json: { ...appt, skip_gcal: true } }];
}

const expiry       = tokens.token_expiry ? new Date(tokens.token_expiry).getTime() : 0;
const needsRefresh = expiry - Date.now() < 5 * 60 * 1000;

return [{ json: {
  ...appt,
  skip_gcal:     false,
  access_token:  tokens.access_token,
  refresh_token: tokens.refresh_token,
  token_expiry:  tokens.token_expiry,
  calendar_id:   tokens.calendar_id ?? 'primary',
  needs_refresh: needsRefresh,
} }];

const refreshResult = $input.first().json;
const prev = $('Avaliar Tokens').first().json;
const newToken  = refreshResult.access_token ?? prev.access_token;
const newExpiry = refreshResult.expires_in
  ? new Date(Date.now() + refreshResult.expires_in * 1000).toISOString()
  : prev.token_expiry;
return [{ json: { ...prev, access_token: newToken, token_expiry: newExpiry } }];

