// Consolida o contexto do agendamento de volta ao fluxo principal
// após o processamento do Google Calendar (ou skip)
const appt = $('Enriquecer com Dados do Banco').first().json;
return [{ json: appt }];

const result = $input.first().json;
const appt   = $('Enriquecer com Dados do Banco').first().json;

const email = result.email    ?? {};
const wa    = result.whatsapp ?? {};

const emailStatus = email.sent ? 'enviado' : (email.skipped ? `pulado (${email.reason})` : `erro: ${email.error}`);
const waStatus    = wa.sent    ? 'enviado' : (wa.skipped    ? `pulado (${wa.reason})`    : `erro: ${wa.error}`);

console.log(`[agenda-upsert v4] ${appt.event} | appt=${appt.appointment_id}`);
console.log(`  e-mail:    ${emailStatus}`);
console.log(`  whatsapp:  ${waStatus}`);

return [{ json: {
  success:        true,
  event:          appt.event,
  appointment_id: appt.appointment_id,
  notifications:  { email, whatsapp: wa },
} }];
